package com.saucedemo.pages;
import com.saucedemo.support.Waits; import org.openqa.selenium.By;
public class CheckoutPage {private static final By FIRST_NAME=By.cssSelector("[data-test='firstName']"),LAST_NAME=By.cssSelector("[data-test='lastName']"),POSTAL_CODE=By.cssSelector("[data-test='postalCode']"),CONTINUE=By.cssSelector("[data-test='continue']"),FINISH=By.cssSelector("[data-test='finish']"),COMPLETE_HEADER=By.cssSelector("[data-test='complete-header']");public void enterCustomerDetails(String first,String last,String postal){Waits.visible(FIRST_NAME).sendKeys(first);Waits.visible(LAST_NAME).sendKeys(last);Waits.visible(POSTAL_CODE).sendKeys(postal);Waits.clickable(CONTINUE).click();}public void finish(){Waits.clickable(FINISH).click();}public boolean isComplete(){return Waits.visible(COMPLETE_HEADER).getText().equals("Thank you for your order!");}}
